const input = $("When Executed by Another Workflow").first().json;

const message = input.message ?? input.content;
const role = input.role ?? "user";

if (typeof message !== "string" || !message.trim()) {
  throw new Error("Memory message is missing or empty.");
}

if (!["user", "assistant"].includes(role)) {
  throw new Error("Role must be user or assistant.");
}

const chatId = String(input.telegram_chat_id ?? "");
const userId = String(input.telegram_user_id ?? "");
const updateId = String(input.telegram_update_id ?? "");

if (!chatId || !userId || !updateId) {
  throw new Error("Telegram identifiers are missing.");
}

const createdAt = new Date().toISOString();

return {
  json: {
    session_id: `telegram:${chatId}:${userId}`,
    message_key: `${createdAt}#${updateId}#${role}`,
    telegram_chat_id: chatId,
    telegram_user_id: userId,
    telegram_update_key: `${chatId}:${updateId}`,
    role,
    content: message.trim(),
    created_at: createdAt
  }
};

const input = $("When Executed by Another Workflow").first().json;

const chatId = String(input.telegram_chat_id ?? "");
const userId = String(input.telegram_user_id ?? "");

if (!chatId || !userId) {
  throw new Error("Telegram chat ID or user ID is missing.");
}

return {
  json: {
    session_id: `telegram:${chatId}:${userId}`,
    telegram_chat_id: chatId,
    telegram_user_id: userId
  }
};

const records = $input.all().map(item => item.json);

const sessionData = $("Code - Prepare Memory Session").first().json;
const sessionId = sessionData.session_id;

if (!sessionId) {
  throw new Error("Conversation session ID is missing.");
}

const validRecords = records.filter(record =>
  record.session_id === sessionId &&
  ["user", "assistant"].includes(record.role) &&
  typeof record.content === "string" &&
  record.content.trim() !== ""
);

validRecords.sort((a, b) =>
  String(a.message_key).localeCompare(String(b.message_key))
);

const recentMessages = validRecords.slice(-20);

const conversationHistory = recentMessages.map(record => ({
  role: record.role,
  content: record.content
}));

const historyText = conversationHistory
  .map(record =>
    `${record.role === "user" ? "Customer" : "Assistant"}: ${record.content}`
  )
  .join("\n\n");

return [{
  json: {
    session_id: sessionId,
    telegram_chat_id: sessionData.telegram_chat_id,
    telegram_user_id: sessionData.telegram_user_id,
    conversation_history: conversationHistory,
    history_text: historyText,
    history_count: conversationHistory.length
  }
}];

const history = $("Code - Format Conversation History").first().json;
const current = $("Code - Prepare Memory Record").first().json;

if (!history?.session_id || !current?.content) {
  throw new Error("Memory context or current message is missing.");
}

return [{
  json: {
    session_id: history.session_id,
    telegram_chat_id: history.telegram_chat_id,
    telegram_user_id: history.telegram_user_id,
    message: current.content,
    conversation_history: history.conversation_history ?? [],
    history_text: history.history_text ?? "",
    history_count: history.history_count ?? 0,
    current_message: current.content,
    current_role: current.role
  }
}];
